            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    target = len(nodes) - 1
    for weight, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, weight])
            total_weight += weight
            if len(mst_edges) == target:
